console.log('Request Details:', JSON.stringify($json, null, 2));
let method = $json.method;
if (!method) {
  method = $json.headers[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

const data = $json;
console.log('Incoming form data ($json):', JSON.stringify(data, null, 2));
return [{ json: {
  departurePort: data.departurePort || 'Not specified',
  cruiseRegion: data.cruiseRegion || 'Not specified',
  startDate: data.startDate || 'N/A',
  endDate: data.endDate || 'N/A',
  cruiseDuration: data.cruiseDuration || 'Not specified',
  tripType: data.tripType || 'N/A',
  onboardPreferences: data.onboardPreferences || [],
  cabinType: data.cabinType || 'Not specified',
  groupSize: data.groupSize || '1',
  ageRange: data.ageRange || [],
  budget: data.budget || '0',
  email: data.email || 'unknown'
} }];

const {
  departurePort,
  cruiseRegion,
  startDate,
  endDate,
  cruiseDuration,
  tripType,
  onboardPreferences,
  cabinType,
  groupSize,
  ageRange,
  budget,
  email
} = $json;
console.log('Preparing prompt with departurePort:', departurePort);
return [{ json: {
  departurePort,
  cruiseRegion,
  startDate,
  endDate,
  cruiseDuration,
  tripType,
  onboardPreferences,
  cabinType,
  groupSize,
  ageRange,
  budget,
  email,
  prompt: `You are a helpful travel agent specializing in cruise trips. Your goal is to create exciting, practical, and well-organized cruise itineraries tailored to each user's preferences. Be friendly, informative, and concise.
- Departure Port: ${departurePort}
- Cruise Region: ${cruiseRegion}
- Cruise Duration: ${cruiseDuration}
- Travel Dates: ${startDate} to ${endDate}
- Trip Type: ${tripType}
- Onboard Preferences: ${Array.isArray(onboardPreferences) ? onboardPreferences.join(', ') : onboardPreferences || 'Not specified'}
- Cabin Type: ${cabinType}
- Group Size: ${groupSize}
- Age Ranges: ${Array.isArray(ageRange) ? ageRange.join(', ') : ageRange || 'Not specified'}
- Budget: $${budget}

Create a complete itinerary for this cruise trip. Include recommendations for:
1. Cruise lines and ships (specific cruise lines and ships that match the user's preferences, with estimated costs per person)
2. Onboard activities (specific activities available on the cruise, with costs if applicable)
3. Shore excursions (specific excursions at each port of call, with costs and booking links)
4. Daily schedule (a day-by-day breakdown of activities, including embarkation and disembarkation days)
5. Estimated food budget (daily cost for dining, considering both complimentary and specialty dining options)
6. A cost summary table (cruise fare, onboard activities, shore excursions, food, total, and remaining budget). This section is mandatory and must always be included. If no costs are available, use placeholder values (e.g., Cruise Fare\t$0). Ensure the table includes all categories: Cruise Fare, Onboard Activities, Shore Excursions, Food, Total, and Remaining Budget, in that order.
7. Travel tips specific to the cruise experience and destinations

Respond in a clean and organized layout with sections. Include hyperlinks to cruise bookings, shore excursions, or activities where relevant, using <a href="URL">Description</a> format. Use real, functional URLs where users can book or learn more (e.g., cruise line websites, excursion providers). Do not use placeholder URLs like "https://example.com". Ensure the Cost Summary section is formatted as a tab-separated table (e.g., Cruise Fare\t$1,200).` }
}];

const cruise = $node['Prepare Cruise Data'].json;
const ai = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output:', ai);
return [{ json: {
  departurePort: cruise.departurePort,
  cruiseRegion: cruise.cruiseRegion,
  startDate: cruise.startDate,
  endDate: cruise.endDate,
  cruiseDuration: cruise.cruiseDuration,
  tripType: cruise.tripType,
  onboardPreferences: cruise.onboardPreferences,
  cabinType: cruise.cabinType,
  groupSize: cruise.groupSize,
  ageRange: cruise.ageRange,
  budget: cruise.budget,
  email: cruise.email,
  itinerary: ai
} }];

const destination = $json.cruiseRegion || 'Your Destination';
const travelDates = `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`;
const departurePort = $json.departurePort || 'Not specified';
const cruiseDuration = $json.cruiseDuration || 'Not specified';
const tripType = $json.tripType || 'N/A';
const onboardPreferences = Array.isArray($json.onboardPreferences) ? $json.onboardPreferences.join(', ') : $json.onboardPreferences || 'Not specified';
const cabinType = $json.cabinType || 'Not specified';
const groupSize = $json.groupSize || 'N/A';
const ageRange = Array.isArray($json.ageRange) ? $json.ageRange.join(', ') : $json.ageRange || 'Not specified';
const budget = $json.budget || 'N/A';
let itineraryRaw = $json.itinerary || 'Itinerary details not available.';
console.log('Initial itineraryRaw:', itineraryRaw);
console.log('Checking for Cost Summary in itineraryRaw (case-insensitive)...');
if (!itineraryRaw.toLowerCase().includes('cost summary:')) {
  console.log('Cost Summary missing, adding fallback');
  itineraryRaw += '\n\nCost Summary:\nCruise Fare\t$0\nOnboard Activities\t$0\nShore Excursions\t$0\nFood\t$0\n<strong>Total</strong>\t<strong>$0</strong>\n<strong>Remaining Budget</strong>\t<strong>$' + budget + '</strong>';
} else {
  console.log('Cost Summary found in itineraryRaw');
}
console.log('itineraryRaw after fallback check:', itineraryRaw);
const itineraryLines = itineraryRaw.split('\n');
let itinerary = '';
let inTable = false;
let tableRows = [];
for (let line of itineraryLines) {
  line = line.trim();
  if (!line) {
    itinerary += '<br>';
    continue;
  }
  if (line.toLowerCase().startsWith('cost summary:')) {
    inTable = true;
    tableRows = [];
    itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    continue;
  }
  if (inTable && (line.startsWith('Total') || line.startsWith('Remaining Budget'))) {
    const [category, cost] = line.split('\t').map(item => item.trim());
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px; background-color: #f0f0f0; font-weight: bold;">${cost}</td></tr>`);
    continue;
  }
  if (inTable && line.includes('\t')) {
    const [category, cost] = line.split('\t').map(item => item.trim());
    tableRows.push(`<tr><td style="border: 1px solid #e0e0e0; padding: 8px;">${category}</td><td style="border: 1px solid #e0e0e0; padding: 8px;">${cost}</td></tr>`);
    continue;
  }
  if (inTable && !line.includes('\t')) {
    inTable = false;
    itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`;
  }
  if (!inTable) {
    if (line.endsWith(':')) {
      itinerary += `<strong style="font-size: 16px; color: #2a4a6e; display: block; margin: 15px 0 5px 0;">${line}</strong>`;
    } else {
      itinerary += line + '<br>';
    }
  }
}
if (inTable) {
  itinerary += `<table style="border-collapse: collapse; width: 100%; margin: 10px 0; font-size: 14px;" cellpadding="0" cellspacing="0">${tableRows.join('')}</table><br>`;
}
console.log('Final itinerary HTML:', itinerary);
const subject = `Your Cruise Itinerary for ${destination} - Voyage Genie`;
const message = `<div style="font-family: 'Helvetica Neue', Arial, sans-serif; max-width: 600px; margin: 0 auto; background-color: #f7f7f7; padding: 25px; border-radius: 10px; box-shadow: 0 4px 8px rgba(0,0,0,0.1);"><div style="background-color: #2a4a6e; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;"><h1 style="color: #ffffff; margin: 0; font-size: 28px;">🚢 Your Cruise Itinerary</h1></div><div style="padding: 25px; background-color: #ffffff; border-radius: 0 0 10px 10px;"><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0; text-align: left;">Departing from: ${departurePort}</h2><h2 style="color: #2a4a6e; font-size: 22px; margin: 0 0 15px 0; text-align: left;">Cruise Region: ${destination}</h2><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Cruise Duration:</strong> ${cruiseDuration}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Travel Dates:</strong> ${travelDates}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Trip Type:</strong> ${tripType}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Onboard Preferences:</strong> ${onboardPreferences}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Cabin Type:</strong> ${cabinType}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Age Range:</strong> ${ageRange}</p><p style="color: #333333; font-size: 16px; margin: 10px 0; line-height: 1.5; text-align: left;"><strong>Budget:</strong> $${budget} (for ${groupSize} travelers)</p><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><h3 style="color: #2a4a6e; font-size: 18px; margin: 0 0 15px 0; text-align: left;">Itinerary Details</h3><div style="background-color: #f9f9f9; padding: 20px; border-radius: 6px; font-size: 14px; line-height: 1.6; color: #333333;">${itinerary}</div><hr style="border: 0; border-top: 1px solid #e0e0e0; margin: 25px 0;"><p style="color: #666666; font-size: 12px; text-align: center; margin: 0;">Generated by <strong>Voyage Genie</strong> 🌟</p></div></div>`;

const sessionId = Date.now().toString();
console.log('Returning itineraryHtml directly with sessionId:', sessionId);

return [{ json: { sessionId: sessionId, itineraryHtml: message, resolvedEmail: $json.email || 'jtran112675@gmail.com', resolvedSubject: subject, resolvedMessage: message, formData: { departurePort: departurePort, cruiseRegion: destination, startDate: $json.startDate, endDate: $json.endDate, budget: budget, groupSize: groupSize } } }];

const url = 'https://exodonprofits.app.n8n.cloud/webhook/send-email';
const payload = {
  resolvedEmail: $json.resolvedEmail,
  resolvedSubject: $json.resolvedSubject,
  resolvedMessage: $json.resolvedMessage
};
try {
  const response = await $http({
    method: 'POST',
    url: url,
    body: payload,
    headers: { 'Content-Type': 'application/json' }
  });
  console.log('Email trigger response:', response);
} catch (error) {
  console.error('Error triggering email workflow:', error.message);
}
return $input.all();
